return [
  {
    json: {
      message: {
        message_id: 9101,
        date: Math.floor(Date.now() / 1000),
        chat: { id: 1+1234567890, title: "Engineering Team Standups", type: "supergroup" },
        from: { id: 80112, first_name: "Alex", last_name: "Rios", username: "alex_rios" },
        text: `#DailyProgress @alex_rios - Thursday, 01 October 2026

[Mobile App Core]
* Optimize offline sync cache - [Done]
* Implement push notification token refresh - [In Progress]
* Fix biometric authentication timeout on Android 15 - [In Progress]

Blocker:
Staging API gateway keeps returning 502 during load testing, blocking payment verification QA.`
      }
    }
  }
];

const item = $json.message || $json;
const text = String(item.text || item.caption || '').trim();
const sender = item.from || {};
const chat = item.chat || {};

let forcedType = '';
if (/(^|\s)#DailyPlan\b/i.test(text)) forcedType = 'Morning Plan';
if (/(^|\s)#DailyProgress\b/i.test(text)) forcedType = 'Afternoon Report';

const now = new Date();
const dateStr = now.toISOString().split('T')[0];

return [{
  json: {
    raw_text: text,
    sender_name: [sender.first_name, sender.last_name].filter(Boolean).join(' ') || sender.username || 'Team Member',
    sender_username: sender.username || '',
    chat_id: chat.id || null,
    chat_title: chat.title || 'Private Chat',
    message_id: item.message_id || null,
    report_date: dateStr,
    forced_type: forcedType
  }
}];

const raw = $json.output ?? $json.text ?? $json;
let parsed;

try {
  if (typeof raw === 'object' && raw !== null) {
    parsed = raw;
  } else {
    const s = String(raw);
    const start = s.indexOf('{');
    const end = s.lastIndexOf('}');
    if (start < 0 || end < start) throw new Error('No JSON object found in LLM output');
    parsed = JSON.parse(s.slice(start, end + 1));
  }
} catch (e) {
  return [{
    json: {
      is_valid_standup: false,
      error_message: e.message
    }
  }];
}

const norm = $('Normalize Telegram Standup').first().json;
const tasks = Array.isArray(parsed.tasks) ? parsed.tasks : [];
const valid = parsed.is_valid_standup !== false && tasks.length > 0;

if (!valid) {
  return [{
    json: {
      is_valid_standup: false,
      sender_name: norm.sender_name,
      raw_text: norm.raw_text,
      chat_id: norm.chat_id,
      message_id: norm.message_id
    }
  }];
}

function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

return tasks.map((t, idx) => {
  const taskName = String(t.task_name || 'Untitled Task').trim();
  const projName = String(t.project_name || 'General').trim();
  const sourceKey = `${norm.report_date}:${norm.sender_username || norm.sender_name}:${hashString(projName + ':' + taskName)}`;

  return {
    json: {
      is_valid_standup: true,
      task_index: idx + 1,
      total_tasks: tasks.length,
      task_name: taskName,
      project_name: projName,
      status: ['To Do', 'In Progress', 'Done', 'On Review'].includes(t.status) ? t.status : 'In Progress',
      priority: ['High', 'Medium', 'Low'].includes(t.priority) ? t.priority : 'Medium',
      notes: String(t.notes || '-').trim(),
      source_key: sourceKey,
      report_date: norm.report_date,
      member_name: norm.sender_name,
      telegram_username: norm.sender_username,
      chat_id: norm.chat_id,
      message_id: norm.message_id,
      has_blocker: Boolean(parsed.has_blocker),
      blocker_severity: String(parsed.blocker_severity || 'None'),
      blocker_details: String(parsed.blocker_details || '-'),
      report_summary: String(parsed.summary || 'Daily progress submitted')
    }
  };
});

